#: Measured on the candidate: what importing the module alone loads -- no other Switchyard module.
DEFAULT_MODULES_LOADED = []

# --- the cases, shared verbatim with `gold435.py` (which ran them on the baseline) ------------------------------------
# A case builds one of the frozen historical layouts, or the list of every layout a release generated, for a role
# count -- or runs `project_role_add`'s recogniser, which reads that list through the launcher, on a synthetic config
# whose layout is in a fresh test-owned tree. Every name the five read on the launcher is a recorder there (the current
# layout, its leaves and the single-row payload, and the five themselves); a case may rebind one there. Nothing is
# written outside the tree and no live layout is read. Recorded, in order: every call with its arguments and the result.
SHAPES = ("_legacy_new_project_stacked_layout_payload", "_legacy_new_project_column_major_layout_payload",
          "_legacy_new_project_sqrt_column_major_layout_payload", "_legacy_new_project_chunked_row_major_layout_payload",
          "_known_generated_project_layout_payloads")
COUNTS = (0, 1, 2, 3, 4, 5, 6, 7, 9, 10, 13)
CASES = {
    **{f"{name}({count})": {"call": "shape", "name": name, "count": count} for name in SHAPES for count in COUNTS},
    "the leaves rebound on the launcher": {"call": "shape", "name": "_legacy_new_project_sqrt_column_major_layout_payload", "count": 5,
                                           "launcher": {"_new_project_layout_leaves": "LEAVES"}},
    "the single row rebound on the launcher": {"call": "shape", "name": "_legacy_new_project_column_major_layout_payload", "count": 3,
                                               "launcher": {"_single_row_layout_payload": "ROW"}},
    "the current layout rebound on the launcher": {"call": "shape", "name": "_known_generated_project_layout_payloads", "count": 3,
                                                   "launcher": {"_new_project_layout_payload": "CURRENT"}},
    "a historical shape rebound on the launcher": {"call": "shape", "name": "_known_generated_project_layout_payloads", "count": 6,
                                                   "launcher": {"_legacy_new_project_stacked_layout_payload": "STACKED"}},
    "the sqrt shape rebound, as column-major's fallback": {"call": "shape", "name": "_legacy_new_project_column_major_layout_payload", "count": 7,
                                                           "launcher": {"_legacy_new_project_sqrt_column_major_layout_payload": "SQRT"}},
    "recognised: a stacked layout from an earlier release": {"call": "recognise", "roles": 6, "layout": ["_legacy_new_project_stacked_layout_payload", 6]},
    "recognised: a chunked row-major layout": {"call": "recognise", "roles": 7, "layout": ["_legacy_new_project_chunked_row_major_layout_payload", 7]},
    "recognised: detached roles are not counted": {"call": "recognise", "roles": 5, "detached": 2, "layout": ["_legacy_new_project_column_major_layout_payload", 3]},
    "not recognised: a layout for another role count": {"call": "recognise", "roles": 6, "layout": ["_legacy_new_project_stacked_layout_payload", 5]},
    "not recognised: an operator's own layout": {"call": "recognise", "roles": 3, "layout": {"Orientation": "Horizontal", "Widgets": []}},
    "not recognised: not JSON": {"call": "recognise", "roles": 3, "layout": "not json"},
    "not recognised: not a generated template": {"call": "recognise", "roles": 6, "layout": ["_legacy_new_project_stacked_layout_payload", 6], "template": False},
}
FUNCTIONS = SHAPES


def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One case against `holder`'s definitions; every name they read a recorder on `t`, the launcher."""
    import json, shutil, tempfile
    from pathlib import Path as _P
    from types import SimpleNamespace
    calls: list = []
    tmp = _P(tempfile.mkdtemp(prefix="syrd435-")).resolve()

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in value.items()}  # insertion order kept: it is what gets written
        if isinstance(value, _P):
            return "PATH " + str(value).replace(str(tmp), "TMP")
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        if isinstance(value, SimpleNamespace):
            return f"NAMESPACE {getattr(value, 'label', '?')}"
        return repr(value)

    def note(seam, /, *args, **kwargs):
        reached.add(seam)
        calls.append([seam, norm(list(args)), norm(dict(kwargs))])

    names = [*FUNCTIONS, "_new_project_layout_leaves", "_single_row_layout_payload", "_new_project_layout_payload", "_is_generated_project_layout_template"]
    saved = {n: getattr(t, n) for n in names}
    try:
        under = {n: getattr(holder, n) for n in FUNCTIONS}

        def passthrough(name):
            def f(*args, **kwargs):
                note(name, *args, **kwargs)
                return saved[name](*args, **kwargs)
            return f

        stand = {"LEAVES": lambda count: note("_new_project_layout_leaves", count) or [{"leaf": i} for i in range(count)],
                 "ROW": lambda leaves: note("_single_row_layout_payload", leaves) or {"row": len(leaves)},
                 "CURRENT": lambda count: note("_new_project_layout_payload", count) or {"current": count},
                 "STACKED": lambda count: note("_legacy_new_project_stacked_layout_payload", count) or {"stacked": count},
                 "SQRT": lambda count: note("_legacy_new_project_sqrt_column_major_layout_payload", count) or {"sqrt": count}}
        on_launcher = {n: passthrough(n) for n in (*FUNCTIONS, "_new_project_layout_leaves", "_single_row_layout_payload", "_new_project_layout_payload")}
        on_launcher["_is_generated_project_layout_template"] = lambda config, *, config_path: note(
            "_is_generated_project_layout_template", config, config_path=config_path) or spec.get("template", True)
        on_launcher.update({k: stand[v] for k, v in spec.get("launcher", {}).items()})
        for n, f in on_launcher.items():
            setattr(t, n, f)
        call = spec["call"]
        try:
            if call == "shape":
                got = under[spec["name"]](spec["count"])
                # The exact text, key order included, as an earlier release would have written it; and the container type.
                return {"result": norm(got), "type": type(got).__name__, "json": json.dumps(got), "calls": calls}
            else:
                from scripts import project_role_add
                layout = tmp / "layout.json"
                raw = spec["layout"]
                if isinstance(raw, list):
                    layout.write_text(json.dumps(saved[raw[0]](raw[1])), encoding="utf-8")
                elif isinstance(raw, dict):
                    layout.write_text(json.dumps(raw), encoding="utf-8")
                else:
                    layout.write_text(raw, encoding="utf-8")
                roles = [SimpleNamespace(detached=i < spec.get("detached", 0)) for i in range(spec["roles"])]
                config = SimpleNamespace(label="config", roles=roles, layout=layout)
                got = project_role_add._is_recognized_generated_project_layout(config, config_path=tmp / "p435.json")
            result = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            result = {"raised": type(exc).__name__, "message": norm(str(exc))}
        return {"result": result, "calls": calls}
    finally:
        for n, f in saved.items():
            setattr(t, n, f)
        shutil.rmtree(tmp)
