def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def result(label):
        return GOLDEN[label]["result"]

    def seams(label):
        return [c[0] for c in GOLDEN[label]["calls"]]

    leaf = {"Command": "", "SessionRestoreId": 0, "WorkingDirectory": ""}
    check(result("_legacy_new_project_stacked_layout_payload(0)") == result("_legacy_new_project_stacked_layout_payload(1)") == leaf
          and result("_legacy_new_project_stacked_layout_payload(5)")["Widgets"][1]["Orientation"] == "Vertical"
          and len(result("_legacy_new_project_stacked_layout_payload(5)")["Widgets"][1]["Widgets"]) == 4,
          "stacked: one leaf alone, else the first role beside a column of the rest")
    check(all(seams(f"{name}({count})")[-1] == "_single_row_layout_payload" and result(f"{name}({count})") == result(f"_legacy_new_project_column_major_layout_payload({count})")
              for name in ("_legacy_new_project_column_major_layout_payload", "_legacy_new_project_chunked_row_major_layout_payload") for count in (2, 3, 4))
          and seams("_legacy_new_project_column_major_layout_payload(5)")[1] == "_legacy_new_project_sqrt_column_major_layout_payload",
          "column-major and chunked row-major: a single row through four roles (the historical threshold, not the live one), then their grids")
    sqrt10, chunked10 = result("_legacy_new_project_sqrt_column_major_layout_payload(10)"), result("_legacy_new_project_chunked_row_major_layout_payload(10)")
    # Ten roles: ceil(sqrt 10) = 4. Square-root columns hold ceil(10 / 4) = 3 roles each (3, 3, 3, 1); chunked rows hold 4 (4, 4, 2).
    check(sqrt10["Orientation"] == "Horizontal" and [len(w["Widgets"]) if "Widgets" in w else 1 for w in sqrt10["Widgets"]] == [3, 3, 3, 1]
          and sqrt10["Widgets"][-1] == {"Command": "", "SessionRestoreId": 9, "WorkingDirectory": ""}
          and chunked10["Orientation"] == "Vertical" and [len(w["Widgets"]) for w in chunked10["Widgets"]] == [4, 4, 2],
          "the square-root grids: columns of ceil(n / ceil(sqrt n)) roles, or rows of ceil(sqrt n) roles, a lone leaf unwrapped")
    known = result("_known_generated_project_layout_payloads(6)")
    check(len(known) == 5 and known[1:] == [result(f"{name}(6)") for name in SHAPES[:4]]
          and seams("_known_generated_project_layout_payloads(6)")[0] == "_new_project_layout_payload",
          "the known layouts: the current one first, then every historical shape in order")
    check(result("the current layout rebound on the launcher")[0] == {"current": 3} and result("a historical shape rebound on the launcher")[1] == {"stacked": 6}
          and result("the sqrt shape rebound, as column-major's fallback") == {"sqrt": 7} and result("the single row rebound on the launcher") == {"row": 3}
          and result("the leaves rebound on the launcher")["Widgets"][0]["Widgets"][0] == {"leaf": 0},
          "the current layout, the leaves, the single row and each sibling are the launcher's when they run")
    check([result(f"recognised: {k}") for k in ("a stacked layout from an earlier release", "a chunked row-major layout", "detached roles are not counted")] == [True, True, True]
          and not any(result(f"not recognised: {k}") for k in ("a layout for another role count", "an operator's own layout", "not JSON", "not a generated template"))
          and "_known_generated_project_layout_payloads" not in seams("not recognised: not a generated template"),
          "project_role_add recognises a layout an earlier release generated, through the launcher's list, and nothing else")


def test_every_launcher_seam_is_reached() -> None:
    # Every function the five read is a recorder on the launcher (the five themselves included), and each is rebound
    # there by a case that changes the answer.
    names = {name for reads in SEAMS.values() for name in reads}
    check(names <= REACHED, f"a recorder on the launcher reached every function: missing {sorted(names - REACHED)}")
    rebound = {name for spec in CASES.values() for name in spec.get("launcher", {})}
    check(rebound == {"_new_project_layout_leaves", "_single_row_layout_payload", "_new_project_layout_payload",
                      "_legacy_new_project_stacked_layout_payload", "_legacy_new_project_sqrt_column_major_layout_payload"},
          f"and the helpers and two siblings rebound there: {sorted(rebound)}")


STRUCTURE = ("test_the_module_loads_only_where_its_defaults_come_from", "test_either_import_order_gives_one_set_of_objects_and_no_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_five_and_its_readers_reach_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"legacy_layouts_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
